INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C1','kor',2,1,'u1',1,'발표하고 듣는 바른 자세 — 발표하는 사람을 바라보며 바른 자세로 끝까지 듣고 고개를 끄덕이거나 중요한 내용은 쓰며 듣기, 발표할 때는 듣는 사람을 보며 알맞은 목소리로 끝까지 분명하게 말하기',ARRAY['2국01-04']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C2','kor',2,1,'u1',1,'소개하는 글 살펴보기 — 민수 글(곱슬이)처럼 무엇을 소개하는지와 그 특징(이름·생김새·하는 일)을 글에서 찾고, 소개하는 글에 들어갈 내용 알기',ARRAY['2국03-03']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C3','kor',2,1,'u1',3,'말차례의 뜻과 필요성 — 말을 주고받을 때 말하는 사람과 듣는 사람이 지키는 순서이며 먼저 말한 사람에게 있음을 알고, 끼어들면 말하는 사람이 당황하고 대화가 끊김을 알기',ARRAY['2국01-03']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C4','kor',2,1,'u1',3,'말차례를 지키는 방법 — 끼어들지 않고 귀 기울여 듣기, 대화 내용과 관계없는 말 하지 않기, 말이 끝났는지 확인하고 말해도 되는지 물어보거나 손짓으로 기회 얻기, 내 차례에는 끝까지 분명하게 말하기',ARRAY['2국01-03']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C5','kor',2,1,'u1',5,'「세상에 둘도 없는 반짝이 신발」 내용 파악 — 라라가 신발을 좋아한 까닭, 시냇가에서 한 짝을 잃은 일, 오빠들의 생각, 짝짝이로 계속 신은 라라의 마음을 찾기',ARRAY['2국01-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C6','kor',2,1,'u1',5,'이야기 속 낱말의 뜻 — 흉·모험·짝의 뜻을 문장 속 쓰임으로 짐작하고 바르게 쓰기',ARRAY['2국01-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C7','kor',2,1,'u1',5,'소중한 물건 소개하며 대화하기 — 라라처럼 나에게 소중한 물건의 이름·색깔과 모양·쓰임·소중한 까닭을 정리해, 말차례를 지키며 친구들과 이야기 나누기',ARRAY['2국01-03']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C8','kor',2,1,'u1',7,'소개하는 글에 들어갈 내용 — 서준·하윤 글을 견주어 이름·모습·좋아하는 것·잘하는 것(+장래 희망·노력할 점)이 들어가야 소개하는 내용이 잘 드러남을 알기',ARRAY['2국03-03']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C9','kor',2,1,'u1',7,'읽을 사람이 궁금해할 내용 고르기 — 친구들이 이미 잘 아는 내용보다 궁금해할 내용을 고르고, 좋아하는 까닭도 함께 쓰기',ARRAY['2국03-03']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C10','kor',2,1,'u1',9,'자신을 소개하는 글 쓰고 다듬기 — 읽을 사람을 정해 항목별로 계획하고 3~5문장으로 쓴 뒤, 점검표로 스스로 확인하고 친구와 돌려 읽으며 고쳐 쓰기',ARRAY['2국03-03']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C11','kor',2,1,'u1',9,'자기소개 발표하고 묻고 칭찬하기 — 쓰기 전에 말로 소개해 보고, 친구 소개를 끝까지 들은 뒤 소개와 관련한 궁금한 점을 묻고, 글씨보다 내용을 칭찬하기',ARRAY['2국01-04']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C12','kor',2,1,'u1',11,'주변 사람을 소개하는 글 쓰기 — 좋아하는 사람·친구·가족을 정해 나와의 관계·이름·모습·좋아하는 것·잘하는 것을 정리하고 특징이 드러나게 써서 전시하고 새롭게 안 내용 나누기',ARRAY['2국03-03']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C13','kor',2,1,'u1',11,'예사소리·된소리와 바른 발음 — 동그라미·바나나·자르다를 된소리로 세게 내지 않고 바르게 읽고, 「옷이 → [오시]」·「작아 → [자가]」·「읽어도 → [일거도]」처럼 받침이 넘어가는 소리를 바르게 읽기(기초 다지기)',ARRAY['2국04-02']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X01','kor',2,'u1',ARRAY['K2-1-u1-C1']::text[],'다른 일을 하거나 딴 데를 보면서도 귀로만 들으면 잘 듣는 것이라고 여긴다','눈은 말하는 사람에게, 끝날 때까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X02','kor',2,'u1',ARRAY['K2-1-u1-C3','K2-1-u1-C4','K2-1-u1-C7','K2-1-u1-C11']::text[],'궁금하거나 할 말이 생기면 상대의 말 중간에 바로 끼어들어도 된다고 여긴다','「말이 끝났나?」 기다린 뒤 「물어봐도 될까?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X03','kor',2,'u1',ARRAY['K2-1-u1-C4']::text[],'더 크게, 더 먼저 말하는 사람이 말차례를 가진다고 여긴다','말차례는 먼저 말한 사람 — 가져오려면 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X04','kor',2,'u1',ARRAY['K2-1-u1-C1','K2-1-u1-C4']::text[],'말하는 사람은 말끝을 흐리거나 바닥을 보고 작게 말해도 된다고 여긴다','듣는 사람을 보며 끝까지 또박또박') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X05','kor',2,'u1',ARRAY['K2-1-u1-C4','K2-1-u1-C7']::text[],'대화 내용과 관계없는 말을 해도 대화가 잘 된다고 여긴다','「지금 무슨 이야기 중이지?」 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X06','kor',2,'u1',ARRAY['K2-1-u1-C2','K2-1-u1-C5']::text[],'글에 없는 내용으로 답하거나 글 속 일을 바꿔 안다','「글 어디에 있지?」 하고 그 문장 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X07','kor',2,'u1',ARRAY['K2-1-u1-C5']::text[],'짝짝이 신발은 쓸모없다고 보고, 한 짝이라도 소중히 여기는 라라의 마음을 헤아리지 못한다','「라라라면 어떤 마음일까?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X08','kor',2,'u1',ARRAY['K2-1-u1-C6']::text[],'흉·모험·짝 같은 낱말의 뜻을 헷갈려 엉뚱한 자리에 쓴다','이야기 속 문장에 넣어 읽어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X09','kor',2,'u1',ARRAY['K2-1-u1-C2','K2-1-u1-C8','K2-1-u1-C10','K2-1-u1-C12']::text[],'소개하는 글에 누구(무엇)를 소개하는지, 이름을 빠뜨린다','첫 문장은 「저는 ○○입니다.」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X10','kor',2,'u1',ARRAY['K2-1-u1-C8','K2-1-u1-C10','K2-1-u1-C12']::text[],'특징을 한 가지만 쓰면 소개하는 글이 다 되었다고 여긴다','이름 · 모습 · 좋아하는 것 · 잘하는 것 네 칸 채우기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X11','kor',2,'u1',ARRAY['K2-1-u1-C9','K2-1-u1-C10']::text[],'읽을 사람이 이미 잘 아는 내용만 골라 쓴다','「친구가 아직 모르는 나는?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X12','kor',2,'u1',ARRAY['K2-1-u1-C2','K2-1-u1-C8','K2-1-u1-C10','K2-1-u1-C12']::text[],'소개하는 대상과 관계없는 내용(친구·동생 이야기 등)을 섞어 쓴다','문장마다 「이게 그 사람 이야기인가?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X13','kor',2,'u1',ARRAY['K2-1-u1-C10','K2-1-u1-C12']::text[],'특징을 길게 끝없이 늘어놓을수록 좋은 소개 글이라고 여긴다','3~5문장, 잘 드러나는 특징만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X14','kor',2,'u1',ARRAY['K2-1-u1-C10','K2-1-u1-C11']::text[],'글을 점검하거나 칭찬할 때 글씨·맞춤법 같은 겉모습만 본다','「소개하는 내용이 잘 드러났나?」 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X15','kor',2,'u1',ARRAY['K2-1-u1-C13']::text[],'된소리로 세게 내거나 받침을 그대로 끊어 읽는 것이 바른 발음이라고 여긴다','세게 말고 바르게, 받침은 뒤로 넘겨') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
