INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#5','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C2',3,'mc','auto','민수가 쓴 글에서 곱슬이의 특징이 아닌 것은?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":5,"concept":"K2-1-u1-C2","difficulty":3,"kind":"mc","stem":"민수가 쓴 글에서 곱슬이의 특징이 아닌 것은?","options":[{"t":"몸집이 아주 커요","correct":true},{"t":"귀가 아주 커요","mis":"K2-1-u1-X06"},{"t":"코끝이 반질거려요","mis":"K2-1-u1-X06"}],"explanation":["몸집은 작아요.","9쪽이에요.","글에서 찾아요."],"asset":{"type":"passage","lines":["저는 강아지를 기르고 있습니다. 곱슬곱슬한 털이 많아 이름도 곱슬이입니다.","몸집은 작지만 귀는 아주 커서 얼굴을 다 덮을 정도입니다.","눈은 동그라면서 크고, 코는 까만색이며 코끝은 반질거립니다.","제가 학교에 갔다 오면 겅중겅중 높이 뛰어오르며 반겨 줍니다.","곱슬이는 우리 집 재롱둥이입니다."],"title":"『국어』 9쪽 민수가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#6','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C2',3,'mc','auto','민수의 글을 읽고 곱슬이가 눈앞에 그려지는 까닭은?',ARRAY['K2-1-u1-X10','K2-1-u1-X12']::text[],false,'{"seq":6,"concept":"K2-1-u1-C2","difficulty":3,"kind":"mc","stem":"민수의 글을 읽고 곱슬이가 눈앞에 그려지는 까닭은?","options":[{"t":"이름과 생김새, 하는 일을 자세히 썼기 때문이에요","correct":true},{"t":"글이 아주 짧기 때문이에요","mis":"K2-1-u1-X10"},{"t":"강아지와 관계없는 내용이 많아서예요","mis":"K2-1-u1-X12"}],"explanation":["자세히 썼어요.","지도서 59쪽이에요.","특징이에요."],"asset":{"type":"passage","lines":["저는 강아지를 기르고 있습니다. 곱슬곱슬한 털이 많아 이름도 곱슬이입니다.","몸집은 작지만 귀는 아주 커서 얼굴을 다 덮을 정도입니다.","눈은 동그라면서 크고, 코는 까만색이며 코끝은 반질거립니다.","제가 학교에 갔다 오면 겅중겅중 높이 뛰어오르며 반겨 줍니다.","곱슬이는 우리 집 재롱둥이입니다."],"title":"『국어』 9쪽 민수가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#7','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C1',3,'mc','auto','평소 발표 습관을 돌아볼 때 고쳐야 할 습관은?',ARRAY['K2-1-u1-X01','K2-1-u1-X04']::text[],false,'{"seq":7,"concept":"K2-1-u1-C1","difficulty":3,"kind":"mc","stem":"평소 발표 습관을 돌아볼 때 고쳐야 할 습관은?","options":[{"t":"친구가 발표할 때 손장난을 하며 듣는 습관","correct":true},{"t":"발표하는 친구를 바라보는 습관","mis":"K2-1-u1-X01"},{"t":"또박또박 끝까지 말하는 습관","mis":"K2-1-u1-X04"}],"explanation":["손장난은 고쳐요.","8쪽 2번이에요.","내 습관을 돌아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#8','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C2',4,'sa','auto','민수는 곱슬이를 우리 집 ○○○이라고 했어요. 빈칸에 들어갈 세 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u1-C2","difficulty":4,"kind":"sa","stem":"민수는 곱슬이를 우리 집 ○○○이라고 했어요. 빈칸에 들어갈 세 글자를 쓰세요.","answer":["재롱둥이"],"explanation":["재롱둥이예요.","9쪽이에요.","글의 끝 문장이에요."],"asset":{"type":"passage","lines":["저는 강아지를 기르고 있습니다. 곱슬곱슬한 털이 많아 이름도 곱슬이입니다.","몸집은 작지만 귀는 아주 커서 얼굴을 다 덮을 정도입니다.","눈은 동그라면서 크고, 코는 까만색이며 코끝은 반질거립니다.","제가 학교에 갔다 오면 겅중겅중 높이 뛰어오르며 반겨 줍니다.","곱슬이는 우리 집 재롱둥이입니다."],"title":"『국어』 9쪽 민수가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#9','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C1',4,'essay','teacher','7쪽 생각 열기 — 오늘 아침 누구를 만나 어떤 대화를 나누었는지 쓰고, 그때 나는 어떻게 듣고 말했는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u1-C1","difficulty":4,"kind":"essay","stem":"7쪽 생각 열기 — 오늘 아침 누구를 만나 어떤 대화를 나누었는지 쓰고, 그때 나는 어떻게 듣고 말했는지 쓰세요.","answer_guide":{"answer":"예: 교문 앞에서 짝 서준이를 만나 오늘 바꾸는 자리 이야기를 했다. 서준이 말을 끝까지 듣고 나서 내 생각을 말했다.","scoring_points":["누구와 어떤 대화를 했는지 썼어요","듣고 말한 모습을 썼어요"]},"explanation":["경험을 써요.","7쪽이에요.","지도서 58쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#10','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C2',4,'essay','teacher','9쪽 4번 — 소개하는 글에 어떤 내용이 들어가면 좋을지 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u1-C2","difficulty":4,"kind":"essay","stem":"9쪽 4번 — 소개하는 글에 어떤 내용이 들어가면 좋을지 두 가지를 쓰세요.","answer_guide":{"answer":"예: 소개하는 대상이 무엇인지 쓴다. 대상의 특징과 읽을 사람이 궁금해할 내용을 쓴다.","scoring_points":["소개하는 대상을 썼어요","특징이나 궁금해할 내용을 썼어요"]},"explanation":["들어갈 내용이에요.","9쪽 4번이에요.","지도서 59쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#1','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C3',1,'mc','auto','10쪽 만화 — 선생님과 친구들은 무엇에 대해 대화했나요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":1,"concept":"K2-1-u1-C3","difficulty":1,"kind":"mc","stem":"10쪽 만화 — 선생님과 친구들은 무엇에 대해 대화했나요?","options":[{"t":"자신의 꿈","correct":true},{"t":"오늘 점심 메뉴","mis":"K2-1-u1-X06"},{"t":"어제 한 축구","mis":"K2-1-u1-X06"}],"explanation":["꿈이에요.","11쪽 2번 (1)이에요.","과학자예요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"지금부터 자신의 꿈을 말해 봅시다."},{"who":"동현","text":"제 꿈은 과학자입니다. 왜냐하면 저는……."},{"who":"친구","text":"선생님, 제 꿈도 과학자예요."},{"who":"동현","text":"(속마음) 내 말이 아직 안 끝났는데 왜 갑자기 끼어들지?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
