INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#7','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C5',3,'mc','auto','라라가 새 신발을 신고 「세상에 둘도 없는 나만의 신발」이라고 한 마음은?',ARRAY['K2-1-u1-X07']::text[],false,'{"seq":7,"concept":"K2-1-u1-C5","difficulty":3,"kind":"mc","stem":"라라가 새 신발을 신고 「세상에 둘도 없는 나만의 신발」이라고 한 마음은?","options":[{"t":"처음으로 오롯이 내 것이 생겨 무척 기쁘고 소중한 마음","correct":true},{"t":"오빠들에게 물려주고 싶은 마음","mis":"K2-1-u1-X07"},{"t":"신발이 싫은 마음","mis":"K2-1-u1-X07"}],"explanation":["소중한 마음이에요.","14쪽이에요.","나만의 신발이에요."],"asset":{"type":"passage","lines":["라라는 오빠 셋의 옷을 물려 입지만, 신발만은 늘 새것이에요.","어느 날 라라는 햇빛에 반짝이는 멋진 새 신발을 만났어요.","소풍 날, 라라는 오빠들과 시냇물을 따라 모험을 떠났어요.","그러다 반짝이 신발 한 짝이 시냇물에 떠내려갔어요.","오빠들은 남은 한 짝을 화분, 연필꽂이, 모빌로 쓰자고 했어요.","라라는 짝짝이가 되어도 남은 신발을 계속 신고 다녔어요.","친구가 짝짝이라고 흉을 보아도 라라는 괜찮다고 했어요."],"title":"『국어』 12~27쪽 「세상에 둘도 없는 반짝이 신발」(제인 고드윈) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#8','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C3',4,'sa','auto','말을 주고받을 때 말하는 사람과 듣는 사람이 지키는 순서를 세 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u1-C3","difficulty":4,"kind":"sa","stem":"말을 주고받을 때 말하는 사람과 듣는 사람이 지키는 순서를 세 글자로 쓰세요.","answer":["말차례"],"explanation":["말차례예요.","11쪽이에요.","순서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#9','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C4',4,'essay','teacher','동현이에게 끼어든 친구가 말차례를 지켰다면 어떻게 말했을지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u1-C4","difficulty":4,"kind":"essay","stem":"동현이에게 끼어든 친구가 말차례를 지켰다면 어떻게 말했을지 쓰세요.","answer_guide":{"answer":"예: 동현이의 말이 끝날 때까지 기다렸다가 「선생님, 저도 말해도 될까요? 제 꿈도 과학자예요.」라고 말했을 것이다.","scoring_points":["기다렸어요","말해도 되는지 물었어요"]},"explanation":["묻고 말해요.","11쪽 도우미예요.","지도서 61쪽이에요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"지금부터 자신의 꿈을 말해 봅시다."},{"who":"동현","text":"제 꿈은 과학자입니다. 왜냐하면 저는……."},{"who":"친구","text":"선생님, 제 꿈도 과학자예요."},{"who":"동현","text":"(속마음) 내 말이 아직 안 끝났는데 왜 갑자기 끼어들지?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#10','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C3',4,'essay','teacher','말차례를 지켜야 하는 까닭을 동현이의 마음과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u1-C3","difficulty":4,"kind":"essay","stem":"말차례를 지켜야 하는 까닭을 동현이의 마음과 함께 쓰세요.","answer_guide":{"answer":"예: 말차례를 지키지 않고 끼어들면 동현이처럼 말하던 사람이 당황하고 하고 싶은 말을 다 하지 못하기 때문이다.","scoring_points":["동현이의 마음을 썼어요","지켜야 하는 까닭을 썼어요"]},"explanation":["까닭이에요.","11쪽이에요.","지도서 61쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#1','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C5',1,'mc','auto','라라는 어디에서 신발을 잃어버렸나요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":1,"concept":"K2-1-u1-C5","difficulty":1,"kind":"mc","stem":"라라는 어디에서 신발을 잃어버렸나요?","options":[{"t":"시냇가","correct":true},{"t":"학교 운동장","mis":"K2-1-u1-X06"},{"t":"시장","mis":"K2-1-u1-X06"}],"explanation":["시냇가예요.","26쪽 내용 알기 (1)이에요.","모험하다가요."],"asset":{"type":"passage","lines":["라라는 오빠 셋의 옷을 물려 입지만, 신발만은 늘 새것이에요.","어느 날 라라는 햇빛에 반짝이는 멋진 새 신발을 만났어요.","소풍 날, 라라는 오빠들과 시냇물을 따라 모험을 떠났어요.","그러다 반짝이 신발 한 짝이 시냇물에 떠내려갔어요.","오빠들은 남은 한 짝을 화분, 연필꽂이, 모빌로 쓰자고 했어요.","라라는 짝짝이가 되어도 남은 신발을 계속 신고 다녔어요.","친구가 짝짝이라고 흉을 보아도 라라는 괜찮다고 했어요."],"title":"『국어』 12~27쪽 「세상에 둘도 없는 반짝이 신발」(제인 고드윈) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#2','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C5',1,'mc','auto','라라는 한 짝 남은 신발을 어떻게 했나요?',ARRAY['K2-1-u1-X07','K2-1-u1-X06']::text[],false,'{"seq":2,"concept":"K2-1-u1-C5","difficulty":1,"kind":"mc","stem":"라라는 한 짝 남은 신발을 어떻게 했나요?","options":[{"t":"계속 신고 다녔어요","correct":true},{"t":"쓰레기통에 버렸어요","mis":"K2-1-u1-X07"},{"t":"친구에게 주었어요","mis":"K2-1-u1-X06"}],"explanation":["계속 신어요.","26쪽 (3)이에요.","소중해요."],"asset":{"type":"passage","lines":["라라는 오빠 셋의 옷을 물려 입지만, 신발만은 늘 새것이에요.","어느 날 라라는 햇빛에 반짝이는 멋진 새 신발을 만났어요.","소풍 날, 라라는 오빠들과 시냇물을 따라 모험을 떠났어요.","그러다 반짝이 신발 한 짝이 시냇물에 떠내려갔어요.","오빠들은 남은 한 짝을 화분, 연필꽂이, 모빌로 쓰자고 했어요.","라라는 짝짝이가 되어도 남은 신발을 계속 신고 다녔어요.","친구가 짝짝이라고 흉을 보아도 라라는 괜찮다고 했어요."],"title":"『국어』 12~27쪽 「세상에 둘도 없는 반짝이 신발」(제인 고드윈) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
