INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#7','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C7',2,'mc','auto','소중한 물건을 소개할 때 넣으면 좋은 내용은?',ARRAY['K2-1-u1-X05','K2-1-u1-X12']::text[],false,'{"seq":7,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"소중한 물건을 소개할 때 넣으면 좋은 내용은?","options":[{"t":"물건의 이름, 색깔과 모양, 소중한 까닭","correct":true},{"t":"친구가 어제 먹은 반찬","mis":"K2-1-u1-X05"},{"t":"내 물건이 더 비싸다는 자랑","mis":"K2-1-u1-X12"}],"explanation":["궁금해할 내용이에요.","27쪽 말할 내용 정하기예요.","지도서 68쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#8','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C4',2,'mc','auto','친구와 대화할 때 말차례를 지키는 말은?',ARRAY['K2-1-u1-X03','K2-1-u1-X02']::text[],false,'{"seq":8,"concept":"K2-1-u1-C4","difficulty":2,"kind":"mc","stem":"친구와 대화할 때 말차례를 지키는 말은?","options":[{"t":"「내가 먼저 말해도 될까?」","correct":true},{"t":"「야, 내 말부터 들어!」","mis":"K2-1-u1-X03"},{"t":"(친구 말 중간에) 「나도, 나도!」","mis":"K2-1-u1-X02"}],"explanation":["묻고 말해요.","27쪽 말풍선이에요.","지도서 68쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#9','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C5',2,'mc','auto','친구가 「신발이 짝짝이잖아.」 하고 흉을 보았을 때 라라는?',ARRAY['K2-1-u1-X07','K2-1-u1-X06']::text[],false,'{"seq":9,"concept":"K2-1-u1-C5","difficulty":2,"kind":"mc","stem":"친구가 「신발이 짝짝이잖아.」 하고 흉을 보았을 때 라라는?","options":[{"t":"「난 괜찮은데.」 하고 상관없다는 듯 말했어요","correct":true},{"t":"울면서 집으로 달려갔어요","mis":"K2-1-u1-X07"},{"t":"친구에게 화를 내며 소리쳤어요","mis":"K2-1-u1-X06"}],"explanation":["괜찮아요.","25쪽이에요.","소중한 마음이에요."],"asset":{"type":"passage","lines":["라라는 오빠 셋의 옷을 물려 입지만, 신발만은 늘 새것이에요.","어느 날 라라는 햇빛에 반짝이는 멋진 새 신발을 만났어요.","소풍 날, 라라는 오빠들과 시냇물을 따라 모험을 떠났어요.","그러다 반짝이 신발 한 짝이 시냇물에 떠내려갔어요.","오빠들은 남은 한 짝을 화분, 연필꽂이, 모빌로 쓰자고 했어요.","라라는 짝짝이가 되어도 남은 신발을 계속 신고 다녔어요.","친구가 짝짝이라고 흉을 보아도 라라는 괜찮다고 했어요."],"title":"『국어』 12~27쪽 「세상에 둘도 없는 반짝이 신발」(제인 고드윈) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
