INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#7','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C4',3,'mc','auto','대화를 이어 가는 말과 쓰임을 바르게 짝 지은 것은?',ARRAY['K2-1-u1-X03']::text[],false,'{"seq":7,"concept":"K2-1-u1-C4","difficulty":3,"kind":"mc","stem":"대화를 이어 가는 말과 쓰임을 바르게 짝 지은 것은?","options":[{"t":"「하고 싶은 말 끝난 거니?」 — 말차례를 가져와도 되는지 확인할 때","correct":true},{"t":"「그랬구나. 나도 그랬겠어.」 — 말차례를 빼앗을 때","mis":"K2-1-u1-X03"},{"t":"「이제 네가 말할 차례야.」 — 내가 계속 말할 때","mis":"K2-1-u1-X03"}],"explanation":["확인해요.","지도서 68쪽이에요.","쓰임이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
