INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#9','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C7',4,'essay','teacher','27쪽 — 라라의 신발처럼 나에게 소중한 물건을 「이름 / 색깔과 모양 / 소중한 까닭」을 넣어 소개하는 말을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u1-C7","difficulty":4,"kind":"essay","stem":"27쪽 — 라라의 신발처럼 나에게 소중한 물건을 「이름 / 색깔과 모양 / 소중한 까닭」을 넣어 소개하는 말을 쓰세요.","answer_guide":{"answer":"예: 제 소중한 물건은 파란 필통입니다. 하늘색 바탕에 고래 그림이 있습니다. 할머니께서 입학 선물로 사 주셔서 소중합니다.","scoring_points":["물건 이름을 썼어요","색깔이나 모양을 썼어요","소중한 까닭을 썼어요"]},"explanation":["소개해요.","27쪽이에요.","궁금해할 내용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#10','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C5',4,'essay','teacher','라라가 흉을 들었을 때 「난 괜찮은데.」라고 한 마음을 짐작하여 쓰고, 나라면 어떻게 했을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u1-C5","difficulty":4,"kind":"essay","stem":"라라가 흉을 들었을 때 「난 괜찮은데.」라고 한 마음을 짐작하여 쓰고, 나라면 어떻게 했을지 쓰세요.","answer_guide":{"answer":"예: 라라는 남의 말보다 신발이 소중한 마음이 더 컸을 것이다. 나라면 조금 속상했겠지만 라라처럼 내 마음을 말했을 것이다.","scoring_points":["라라의 마음을 짐작했어요","나라면 어떻게 할지 썼어요"]},"explanation":["공감해요.","지도서 66쪽이에요.","인물과 소통해요."],"asset":{"type":"passage","lines":["라라는 오빠 셋의 옷을 물려 입지만, 신발만은 늘 새것이에요.","어느 날 라라는 햇빛에 반짝이는 멋진 새 신발을 만났어요.","소풍 날, 라라는 오빠들과 시냇물을 따라 모험을 떠났어요.","그러다 반짝이 신발 한 짝이 시냇물에 떠내려갔어요.","오빠들은 남은 한 짝을 화분, 연필꽂이, 모빌로 쓰자고 했어요.","라라는 짝짝이가 되어도 남은 신발을 계속 신고 다녔어요.","친구가 짝짝이라고 흉을 보아도 라라는 괜찮다고 했어요."],"title":"『국어』 12~27쪽 「세상에 둘도 없는 반짝이 신발」(제인 고드윈) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#1','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C8',1,'mc','auto','서준이와 하윤이는 각각 누구를 소개하고 있나요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":1,"concept":"K2-1-u1-C8","difficulty":1,"kind":"mc","stem":"서준이와 하윤이는 각각 누구를 소개하고 있나요?","options":[{"t":"자신","correct":true},{"t":"가족","mis":"K2-1-u1-X06"},{"t":"기르는 동물","mis":"K2-1-u1-X06"}],"explanation":["자신이에요.","29쪽 (1) 예시 답안이에요.","자기소개예요."],"asset":{"type":"passage","lines":["㉮ 저는 김서준입니다. 저는 달리기를 좋아합니다.","㉯ 저는 정하윤입니다. 저는 머리를 묶고 다닙니다.","지금은 노란색 긴팔옷을 입고 있습니다.","저는 종이접기를 좋아해서 항상 색종이를 가지고 다닙니다.","저는 그림을 잘 그립니다.","만화 주인공 그림을 그려서 친구에게 주기도 합니다."],"title":"『국어』 29쪽 서준이와 하윤이가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
