INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#3','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C8',3,'ox','auto','「저는 김서준입니다. 저는 달리기를 좋아합니다.」만 써도 자신을 충분히 잘 소개한 글이다.',ARRAY['K2-1-u1-X10']::text[],false,'{"seq":3,"concept":"K2-1-u1-C8","difficulty":3,"kind":"ox","stem":"「저는 김서준입니다. 저는 달리기를 좋아합니다.」만 써도 자신을 충분히 잘 소개한 글이다.","answer":"X","reason_options":[{"t":"모습·잘하는 것 등이 없어 읽는 사람이 서준이를 잘 알 수 없어서","correct":true},{"t":"짧을수록 좋은 글이라서","mis":"K2-1-u1-X10"}],"mis":"K2-1-u1-X10","explanation":["더 자세히요.","29쪽이에요.","지도서 72쪽이에요."],"asset":{"type":"passage","lines":["㉮ 저는 김서준입니다. 저는 달리기를 좋아합니다.","㉯ 저는 정하윤입니다. 저는 머리를 묶고 다닙니다.","지금은 노란색 긴팔옷을 입고 있습니다.","저는 종이접기를 좋아해서 항상 색종이를 가지고 다닙니다.","저는 그림을 잘 그립니다.","만화 주인공 그림을 그려서 친구에게 주기도 합니다."],"title":"『국어』 29쪽 서준이와 하윤이가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#4','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C9',3,'error','auto','친구가 지도서의 「친구 소개」를 읽었어요. 무엇을 고쳐야 하나요?',ARRAY['K2-1-u1-X09','K2-1-u1-X12','K2-1-u1-X10']::text[],false,'{"seq":4,"concept":"K2-1-u1-C9","difficulty":3,"kind":"error","stem":"친구가 지도서의 「친구 소개」를 읽었어요. 무엇을 고쳐야 하나요?","options":[{"t":"누구를 소개하는지 이름이 없고, 모습·좋아하는 것·잘하는 것이 자세하지 않아요","correct":true,"mis_target":"K2-1-u1-X09"},{"t":"「엄마」를 「아빠」로 고쳐요","mis":"K2-1-u1-X12"},{"t":"고칠 곳이 없어요","mis":"K2-1-u1-X10"}],"explanation":["이름부터요.","지도서 73쪽이에요.","소개하는 방법이에요."],"asset":{"type":"passage","lines":["엄마, 걔는 우리 반이에요. 축구를 좋아하는 것 같아요.","집에 올 때 만났는데 어디 사는지 모르겠어요."],"title":"지도서 「친구 소개」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
