INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#8','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C8',4,'sa','auto','30쪽 보기에는 이름, 모습, 좋아하는 것, 그리고 ○○○ 것이 있어요. 빈칸 세 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u1-C8","difficulty":4,"kind":"sa","stem":"30쪽 보기에는 이름, 모습, 좋아하는 것, 그리고 ○○○ 것이 있어요. 빈칸 세 글자를 쓰세요.","answer":["잘하는"],"explanation":["잘하는 것이에요.","30쪽이에요.","네 칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#9','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C8',4,'essay','teacher','31쪽 5번 — 자신을 소개할 내용을 「이름 / 모습 / 좋아하는 것 / 잘하는 것」으로 정리해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u1-C8","difficulty":4,"kind":"essay","stem":"31쪽 5번 — 자신을 소개할 내용을 「이름 / 모습 / 좋아하는 것 / 잘하는 것」으로 정리해 쓰세요.","answer_guide":{"answer":"예: 이름 — 한지민 / 모습 — 앞머리가 있고 안경을 썼다 / 좋아하는 것 — 떡볶이, 매콤해서 / 잘하는 것 — 줄넘기","scoring_points":["네 항목을 모두 썼어요","좋아하는 까닭도 썼어요"]},"explanation":["항목별로요.","31쪽이에요.","지도서 73쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#10','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C9',4,'essay','teacher','「친구 소개」를 소개하는 글 쓰는 방법에 맞게 고쳐 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u1-C9","difficulty":4,"kind":"essay","stem":"「친구 소개」를 소개하는 글 쓰는 방법에 맞게 고쳐 쓰세요.","answer_guide":{"answer":"예: 엄마, 우리 반 친구 이도윤을 소개할게요. 도윤이는 키가 크고 웃음이 많아요. 축구를 좋아해서 쉬는 시간마다 공을 차고, 골을 잘 넣어요.","scoring_points":["이름을 넣었어요","모습·좋아하는 것·잘하는 것을 넣었어요"]},"explanation":["고쳐 써요.","지도서 73쪽이에요.","보충해요."],"asset":{"type":"passage","lines":["엄마, 걔는 우리 반이에요. 축구를 좋아하는 것 같아요.","집에 올 때 만났는데 어디 사는지 모르겠어요."],"title":"지도서 「친구 소개」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#1','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C10',1,'mc','auto','32쪽 계획하기 — 자신을 소개하는 글을 읽을 사람은?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":1,"concept":"K2-1-u1-C10","difficulty":1,"kind":"mc","stem":"32쪽 계획하기 — 자신을 소개하는 글을 읽을 사람은?","options":[{"t":"우리 반 친구들","correct":true},{"t":"모르는 외국 사람","mis":"K2-1-u1-X11"},{"t":"아무도 없어요","mis":"K2-1-u1-X11"}],"explanation":["친구들이에요.","32쪽 예시 답안이에요.","읽을 사람이에요."],"asset":{"type":"passage","lines":["글을 쓰는 까닭: 나를 소개하려고 · 읽을 사람: 우리 반 친구들","이름: 김윤승","모습: 얼굴이 둥글고 항상 웃는 얼굴이다.","좋아하는 것: 코알라, 귀여운 동물","잘하는 것: 역할놀이","더 소개하고 싶은 내용: 역할에 맞는 목소리 연습을 꾸준히 한다는 점"],"title":"『국어』 32쪽 계획하기 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#2','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C10',1,'mc','auto','김윤승이 계획한 「잘하는 것」은?',ARRAY['K2-1-u1-X10']::text[],false,'{"seq":2,"concept":"K2-1-u1-C10","difficulty":1,"kind":"mc","stem":"김윤승이 계획한 「잘하는 것」은?","options":[{"t":"역할놀이","correct":true},{"t":"코알라","mis":"K2-1-u1-X10"},{"t":"웃는 얼굴","mis":"K2-1-u1-X10"}],"explanation":["역할놀이예요.","32쪽 예시 답안이에요.","항목이에요."],"asset":{"type":"passage","lines":["글을 쓰는 까닭: 나를 소개하려고 · 읽을 사람: 우리 반 친구들","이름: 김윤승","모습: 얼굴이 둥글고 항상 웃는 얼굴이다.","좋아하는 것: 코알라, 귀여운 동물","잘하는 것: 역할놀이","더 소개하고 싶은 내용: 역할에 맞는 목소리 연습을 꾸준히 한다는 점"],"title":"『국어』 32쪽 계획하기 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
