INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#7','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C10',3,'mc','auto','친구들과 글을 돌려 읽을 때 알맞은 것은?',ARRAY['K2-1-u1-X14','K2-1-u1-X12']::text[],false,'{"seq":7,"concept":"K2-1-u1-C10","difficulty":3,"kind":"mc","stem":"친구들과 글을 돌려 읽을 때 알맞은 것은?","options":[{"t":"읽을 사람이 궁금해할 내용을 잘 썼는지 중심으로 고쳐 쓸 부분을 말해 줘요","correct":true},{"t":"틀린 글자만 빨간색으로 표시해요","mis":"K2-1-u1-X14"},{"t":"친구 글을 내 글로 바꿔 써 줘요","mis":"K2-1-u1-X12"}],"explanation":["내용 중심이에요.","35쪽 (2)예요.","지도서 76쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#8','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C10',4,'sa','auto','소개하는 글을 다 쓴 뒤 스스로 확인할 때 쓰는 표를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u1-C10","difficulty":4,"kind":"sa","stem":"소개하는 글을 다 쓴 뒤 스스로 확인할 때 쓰는 표를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["점검표"],"explanation":["점검표예요.","35쪽이에요.","스스로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#9','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C10',4,'essay','teacher','34쪽 — 나를 소개하는 글을 3~5문장으로 쓰세요(이름·모습·좋아하는 것·잘하는 것 넣기).','{}'::text[],false,'{"seq":9,"concept":"K2-1-u1-C10","difficulty":4,"kind":"essay","stem":"34쪽 — 나를 소개하는 글을 3~5문장으로 쓰세요(이름·모습·좋아하는 것·잘하는 것 넣기).","answer_guide":{"answer":"예: 저는 오하람입니다. 저는 앞머리가 있고 웃을 때 눈이 반달이 됩니다. 저는 고양이를 좋아해서 고양이 그림을 자주 그립니다. 저는 훌라후프를 잘 돌립니다.","scoring_points":["이름을 썼어요","모습·좋아하는 것·잘하는 것을 썼어요","3~5문장으로 썼어요"]},"explanation":["나를 소개해요.","34쪽이에요.","지도서 76쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#10','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C11',4,'essay','teacher','친구가 쓴 자기소개 글을 읽었다고 생각하고, 내용을 칭찬하는 쪽지를 한두 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u1-C11","difficulty":4,"kind":"essay","stem":"친구가 쓴 자기소개 글을 읽었다고 생각하고, 내용을 칭찬하는 쪽지를 한두 문장으로 쓰세요.","answer_guide":{"answer":"예: 블록으로 캐릭터를 만들었다니 손재주가 정말 좋구나. 네가 로봇 과학자가 되면 멋진 로봇을 만들 것 같아.","scoring_points":["글의 내용을 칭찬했어요","까닭이 드러나요"]},"explanation":["칭찬 쪽지예요.","35쪽 더 나아가기예요.","지도서 77쪽이에요."],"asset":{"type":"passage","lines":["저는 안경을 쓰고 말랐습니다.","저는 블록 조립을 좋아하고 모양 만들기를 잘합니다.","저번에는 블록으로 만화 캐릭터를 만들어서 칭찬을 받았습니다.","저는 커서 로봇 과학자가 되고 싶습니다."],"title":"지도서 박준형이 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
