INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#8','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C12',4,'sa','auto','좋아하는 사람을 소개하는 글을 쓴 뒤 붙여서 전시하는 곳은 학급 ○○○이에요. 세 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u1-C12","difficulty":4,"kind":"sa","stem":"좋아하는 사람을 소개하는 글을 쓴 뒤 붙여서 전시하는 곳은 학급 ○○○이에요. 세 글자를 쓰세요.","answer":["알림판"],"explanation":["알림판이에요.","36쪽이에요.","전시해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#9','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C12',4,'essay','teacher','가족 가운데 한 사람을 골라 「나와의 관계(이름) / 모습 / 좋아하는 것 / 잘하는 것」을 넣어 친구에게 소개하는 글을 3~5문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u1-C12","difficulty":4,"kind":"essay","stem":"가족 가운데 한 사람을 골라 「나와의 관계(이름) / 모습 / 좋아하는 것 / 잘하는 것」을 넣어 친구에게 소개하는 글을 3~5문장으로 쓰세요.","answer_guide":{"answer":"예: 우리 아빠 김도현을 소개합니다. 아빠는 키가 크고 수염이 있습니다. 아빠는 주말마다 등산하는 것을 좋아합니다. 아빠는 김치볶음밥을 정말 잘 만듭니다.","scoring_points":["관계와 이름을 썼어요","특징을 두 가지 넘게 썼어요","3~5문장으로 썼어요"]},"explanation":["가족 소개예요.","지도서 81쪽이에요.","특징이 드러나게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#10','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C12',4,'essay','teacher','친구들이 소개한 글을 읽고 새롭게 안 내용을 발표하는 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u1-C12","difficulty":4,"kind":"essay","stem":"친구들이 소개한 글을 읽고 새롭게 안 내용을 발표하는 말을 쓰세요.","answer_guide":{"answer":"예: 지우가 소개한 이모는 제빵사라서 빵을 정말 잘 만드신대. 나도 이모가 만든 크림빵을 먹어 보고 싶어.","scoring_points":["누가 소개한 누구인지 썼어요","새롭게 안 내용을 썼어요"]},"explanation":["새롭게 안 내용이에요.","36쪽 ③이에요.","발표해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
