INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#4','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C4',1,'mc','auto','「친구가 말할 때에는 (    ) 안 돼.」',ARRAY['K2-1-u1-X02','K2-1-u1-X05']::text[],false,'{"seq":4,"concept":"K2-1-u1-C4","difficulty":1,"kind":"mc","stem":"「친구가 말할 때에는 (    ) 안 돼.」","options":[{"t":"끼어들면","correct":true},{"t":"귀 기울여","mis":"K2-1-u1-X02"},{"t":"관계없는","mis":"K2-1-u1-X05"}],"explanation":["끼어들면이에요.","11쪽이에요.","보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#5','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C5',1,'mc','auto','라라는 어디에서 신발을 잃어버렸나요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":5,"concept":"K2-1-u1-C5","difficulty":1,"kind":"mc","stem":"라라는 어디에서 신발을 잃어버렸나요?","options":[{"t":"시냇가","correct":true},{"t":"운동장","mis":"K2-1-u1-X06"},{"t":"시장","mis":"K2-1-u1-X06"}],"explanation":["시냇가예요.","26쪽이에요.","모험이에요."],"asset":{"type":"passage","lines":["라라는 오빠 셋의 옷을 물려 입지만, 신발만은 늘 새것이에요.","어느 날 라라는 햇빛에 반짝이는 멋진 새 신발을 만났어요.","소풍 날, 라라는 오빠들과 시냇물을 따라 모험을 떠났어요.","그러다 반짝이 신발 한 짝이 시냇물에 떠내려갔어요.","오빠들은 남은 한 짝을 화분, 연필꽂이, 모빌로 쓰자고 했어요.","라라는 짝짝이가 되어도 남은 신발을 계속 신고 다녔어요.","친구가 짝짝이라고 흉을 보아도 라라는 괜찮다고 했어요."],"title":"『국어』 12~27쪽 「세상에 둘도 없는 반짝이 신발」(제인 고드윈) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#6','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C6',1,'mc','auto','「위험을 무릅쓰고 하는 일」을 뜻하는 낱말은?',ARRAY['K2-1-u1-X08']::text[],false,'{"seq":6,"concept":"K2-1-u1-C6","difficulty":1,"kind":"mc","stem":"「위험을 무릅쓰고 하는 일」을 뜻하는 낱말은?","options":[{"t":"모험","correct":true},{"t":"흉","mis":"K2-1-u1-X08"},{"t":"짝","mis":"K2-1-u1-X08"}],"explanation":["모험이에요.","27쪽이에요.","낱말 알기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#7','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C8',1,'mc','auto','「저는 그림을 잘 그립니다.」는 무엇을 소개한 문장인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":7,"concept":"K2-1-u1-C8","difficulty":1,"kind":"mc","stem":"「저는 그림을 잘 그립니다.」는 무엇을 소개한 문장인가요?","options":[{"t":"잘하는 것","correct":true},{"t":"이름","mis":"K2-1-u1-X06"},{"t":"모습","mis":"K2-1-u1-X06"}],"explanation":["잘하는 것이에요.","30쪽이에요.","보기예요."],"asset":{"type":"passage","lines":["㉮ 저는 김서준입니다. 저는 달리기를 좋아합니다.","㉯ 저는 정하윤입니다. 저는 머리를 묶고 다닙니다.","지금은 노란색 긴팔옷을 입고 있습니다.","저는 종이접기를 좋아해서 항상 색종이를 가지고 다닙니다.","저는 그림을 잘 그립니다.","만화 주인공 그림을 그려서 친구에게 주기도 합니다."],"title":"『국어』 29쪽 서준이와 하윤이가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#8','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C13',1,'mc','auto','「동그라미」의 알맞은 발음은?',ARRAY['K2-1-u1-X15']::text[],false,'{"seq":8,"concept":"K2-1-u1-C13","difficulty":1,"kind":"mc","stem":"「동그라미」의 알맞은 발음은?","options":[{"t":"[동그라미]","correct":true},{"t":"[똥그라미]","mis":"K2-1-u1-X15"},{"t":"[동끄라미]","mis":"K2-1-u1-X15"}],"explanation":["[동그라미]예요.","40쪽이에요.","세게 내지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#9','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C2',2,'mc','auto','민수가 쓴 글에서 곱슬이의 특징으로 알맞은 것은?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":9,"concept":"K2-1-u1-C2","difficulty":2,"kind":"mc","stem":"민수가 쓴 글에서 곱슬이의 특징으로 알맞은 것은?","options":[{"t":"귀는 아주 커서 얼굴을 다 덮을 정도예요","correct":true},{"t":"몸집이 아주 커요","mis":"K2-1-u1-X06"},{"t":"코가 하얀색이에요","mis":"K2-1-u1-X06"}],"explanation":["귀가 커요.","9쪽이에요.","생김새예요."],"asset":{"type":"passage","lines":["저는 강아지를 기르고 있습니다. 곱슬곱슬한 털이 많아 이름도 곱슬이입니다.","몸집은 작지만 귀는 아주 커서 얼굴을 다 덮을 정도입니다.","눈은 동그라면서 크고, 코는 까만색이며 코끝은 반질거립니다.","제가 학교에 갔다 오면 겅중겅중 높이 뛰어오르며 반겨 줍니다.","곱슬이는 우리 집 재롱둥이입니다."],"title":"『국어』 9쪽 민수가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#10','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C4',2,'mc','auto','말차례를 가져오고 싶을 때 알맞은 방법은?',ARRAY['K2-1-u1-X03','K2-1-u1-X02']::text[],false,'{"seq":10,"concept":"K2-1-u1-C4","difficulty":2,"kind":"mc","stem":"말차례를 가져오고 싶을 때 알맞은 방법은?","options":[{"t":"말이 끝났는지 확인하고 「내가 말해도 될까?」 물어본 뒤에 말해요","correct":true},{"t":"더 크게 말해요","mis":"K2-1-u1-X03"},{"t":"말을 막아요","mis":"K2-1-u1-X02"}],"explanation":["묻고 말해요.","11쪽이에요.","지도서 61쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#11','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C5',2,'match','auto','오빠와 신발 한 짝을 어떻게 하자고 했는지 이어 보세요.','{}'::text[],false,'{"seq":11,"concept":"K2-1-u1-C5","difficulty":2,"kind":"match","stem":"오빠와 신발 한 짝을 어떻게 하자고 했는지 이어 보세요.","pairs":[{"l":"월터","r":"화분으로 쓰자"},{"l":"맥스","r":"연필꽂이로 쓰자"},{"l":"핀","r":"모빌처럼 걸어 두자"}],"mis":"K2-1-u1-X06","explanation":["오빠들 생각이에요.","26쪽이에요.","저마다 달라요."],"asset":{"type":"passage","lines":["라라는 오빠 셋의 옷을 물려 입지만, 신발만은 늘 새것이에요.","어느 날 라라는 햇빛에 반짝이는 멋진 새 신발을 만났어요.","소풍 날, 라라는 오빠들과 시냇물을 따라 모험을 떠났어요.","그러다 반짝이 신발 한 짝이 시냇물에 떠내려갔어요.","오빠들은 남은 한 짝을 화분, 연필꽂이, 모빌로 쓰자고 했어요.","라라는 짝짝이가 되어도 남은 신발을 계속 신고 다녔어요.","친구가 짝짝이라고 흉을 보아도 라라는 괜찮다고 했어요."],"title":"『국어』 12~27쪽 「세상에 둘도 없는 반짝이 신발」(제인 고드윈) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#12','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C7',2,'mc','auto','소중한 물건을 소개할 때 넣으면 좋은 내용은?',ARRAY['K2-1-u1-X05','K2-1-u1-X12']::text[],false,'{"seq":12,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"소중한 물건을 소개할 때 넣으면 좋은 내용은?","options":[{"t":"물건 이름, 색깔과 모양, 소중한 까닭","correct":true},{"t":"친구가 먹은 반찬","mis":"K2-1-u1-X05"},{"t":"더 비싸다는 자랑","mis":"K2-1-u1-X12"}],"explanation":["궁금해할 내용이에요.","27쪽이에요.","지도서 68쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#13','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C9',2,'mc','auto','자신을 소개할 때 고르면 더 좋은 내용은?',ARRAY['K2-1-u1-X11','K2-1-u1-X12']::text[],false,'{"seq":13,"concept":"K2-1-u1-C9","difficulty":2,"kind":"mc","stem":"자신을 소개할 때 고르면 더 좋은 내용은?","options":[{"t":"친구들이 아직 잘 모르고 궁금해할 내용","correct":true},{"t":"친구들이 다 아는 내용","mis":"K2-1-u1-X11"},{"t":"나와 관계없는 내용","mis":"K2-1-u1-X12"}],"explanation":["궁금해할 내용이에요.","31쪽이에요.","읽을 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#14','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C10',2,'mc','auto','자신을 소개하는 글을 읽을 사람은?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":14,"concept":"K2-1-u1-C10","difficulty":2,"kind":"mc","stem":"자신을 소개하는 글을 읽을 사람은?","options":[{"t":"우리 반 친구들","correct":true},{"t":"모르는 외국 사람","mis":"K2-1-u1-X11"},{"t":"아무도 없어요","mis":"K2-1-u1-X11"}],"explanation":["친구들이에요.","32쪽이에요.","읽을 사람이에요."],"asset":{"type":"passage","lines":["글을 쓰는 까닭: 나를 소개하려고 · 읽을 사람: 우리 반 친구들","이름: 김윤승","모습: 얼굴이 둥글고 항상 웃는 얼굴이다.","좋아하는 것: 코알라, 귀여운 동물","잘하는 것: 역할놀이","더 소개하고 싶은 내용: 역할에 맞는 목소리 연습을 꾸준히 한다는 점"],"title":"『국어』 32쪽 계획하기 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#15','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C11',2,'mc','auto','이준영이 「저는 치타를 무척 좋아합니다.」라고 했어요. 알맞은 질문은?',ARRAY['K2-1-u1-X02','K2-1-u1-X05']::text[],false,'{"seq":15,"concept":"K2-1-u1-C11","difficulty":2,"kind":"mc","stem":"이준영이 「저는 치타를 무척 좋아합니다.」라고 했어요. 알맞은 질문은?","options":[{"t":"「왜 치타를 좋아하니?」","correct":true},{"t":"(중간에) 「너 키 몇이야?」","mis":"K2-1-u1-X02"},{"t":"「사자 이야기 해.」","mis":"K2-1-u1-X05"}],"explanation":["관련 질문이에요.","33쪽이에요.","궁금한 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#16','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C12',2,'mc','auto','좋아하는 사람을 소개하는 활동에서 가장 먼저 할 일은?',ARRAY['K2-1-u1-X13']::text[],false,'{"seq":16,"concept":"K2-1-u1-C12","difficulty":2,"kind":"mc","stem":"좋아하는 사람을 소개하는 활동에서 가장 먼저 할 일은?","options":[{"t":"소개할 사람을 정하고 내용 정리하기","correct":true},{"t":"알림판에 붙이기","mis":"K2-1-u1-X13"},{"t":"칭찬 쪽지 쓰기","mis":"K2-1-u1-X13"}],"explanation":["정하고 정리해요.","36쪽이에요.","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
