INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#18','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C12',3,'error','auto','국어활동 11쪽 민희의 글에서 자신을 소개하는 내용이 아닌 문장은?',ARRAY['K2-1-u1-X12','K2-1-u1-X09']::text[],false,'{"seq":18,"concept":"K2-1-u1-C12","difficulty":3,"kind":"error","stem":"국어활동 11쪽 민희의 글에서 자신을 소개하는 내용이 아닌 문장은?","options":[{"t":"「제 친구는 지난 주말에 자전거를 탔습니다.」","correct":true,"mis_target":"K2-1-u1-X12"},{"t":"「저는 종이접기를 잘합니다.」","mis":"K2-1-u1-X12"},{"t":"「제 이름은 김민희입니다.」","mis":"K2-1-u1-X09"}],"explanation":["친구 이야기예요.","국어활동 11쪽이에요.","민희 이야기만 남겨요."],"asset":{"type":"passage","lines":["제 이름은 김민희입니다. 저는 2학년입니다.","저는 눈이 큽니다. 좋아하는 색깔은 주황색입니다.","음식은 된장찌개를 좋아합니다.","제 친구는 지난 주말에 자전거를 탔습니다.","저는 종이접기를 잘합니다.","달리기도 잘한다는 말을 많이 듣습니다.","제 동생은 저와 같이 노는 것을 좋아합니다.","제 동생은 생일에 친구들을 초대하려 합니다."],"title":"『국어활동』 11쪽 민희가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#19','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C3',3,'ox','auto','목소리가 크고 먼저 소리친 사람이 말차례를 가진다.',ARRAY['K2-1-u1-X03']::text[],false,'{"seq":19,"concept":"K2-1-u1-C3","difficulty":3,"kind":"ox","stem":"목소리가 크고 먼저 소리친 사람이 말차례를 가진다.","answer":"X","reason_options":[{"t":"말차례는 먼저 말을 시작한 사람에게 있고, 가져오려면 묻거나 기다려야 해서","correct":true},{"t":"큰 소리가 이겨서","mis":"K2-1-u1-X03"}],"mis":"K2-1-u1-X03","explanation":["크기가 아니에요.","지도서 61쪽이에요.","순서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#20','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C9',3,'mc','auto','39쪽 「읽을 사람이 잘 알고 있는 내용을 쓴다.」를 바르게 고치면?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":20,"concept":"K2-1-u1-C9","difficulty":3,"kind":"mc","stem":"39쪽 「읽을 사람이 잘 알고 있는 내용을 쓴다.」를 바르게 고치면?","options":[{"t":"읽을 사람이 궁금해할 만한 내용을 고른다","correct":true},{"t":"읽을 사람이 싫어하는 내용을 쓴다","mis":"K2-1-u1-X11"},{"t":"읽을 사람은 생각하지 않는다","mis":"K2-1-u1-X11"}],"explanation":["궁금해할 내용이에요.","지도서 82쪽이에요.","보충 학습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#21','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C5',3,'mc','auto','라라가 짝짝이 신발을 계속 신고 다닌 까닭은?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":21,"concept":"K2-1-u1-C5","difficulty":3,"kind":"mc","stem":"라라가 짝짝이 신발을 계속 신고 다닌 까닭은?","options":[{"t":"남은 한 짝도 세상에 둘도 없는 소중한 신발이라서","correct":true},{"t":"새 신발을 살 돈이 없어서","mis":"K2-1-u1-X06"},{"t":"엄마가 꼭 신으라고 해서","mis":"K2-1-u1-X06"}],"explanation":["소중해요.","지도서 66쪽이에요.","라라의 마음이에요."],"asset":{"type":"passage","lines":["라라는 오빠 셋의 옷을 물려 입지만, 신발만은 늘 새것이에요.","어느 날 라라는 햇빛에 반짝이는 멋진 새 신발을 만났어요.","소풍 날, 라라는 오빠들과 시냇물을 따라 모험을 떠났어요.","그러다 반짝이 신발 한 짝이 시냇물에 떠내려갔어요.","오빠들은 남은 한 짝을 화분, 연필꽂이, 모빌로 쓰자고 했어요.","라라는 짝짝이가 되어도 남은 신발을 계속 신고 다녔어요.","친구가 짝짝이라고 흉을 보아도 라라는 괜찮다고 했어요."],"title":"『국어』 12~27쪽 「세상에 둘도 없는 반짝이 신발」(제인 고드윈) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#22','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C13',3,'mc','auto','바르게 발음한 것은?',ARRAY['K2-1-u1-X15']::text[],false,'{"seq":22,"concept":"K2-1-u1-C13","difficulty":3,"kind":"mc","stem":"바르게 발음한 것은?","options":[{"t":"「작아」 → [자가]","correct":true},{"t":"「옷이」 → [오디]","mis":"K2-1-u1-X15"},{"t":"「읽어도」 → [이거도]","mis":"K2-1-u1-X15"}],"explanation":["[자가]예요.","41쪽이에요.","받침이 넘어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#23','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C3',4,'sa','auto','말을 주고받을 때 말하는 사람과 듣는 사람이 지키는 순서를 세 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u1-C3","difficulty":4,"kind":"sa","stem":"말을 주고받을 때 말하는 사람과 듣는 사람이 지키는 순서를 세 글자로 쓰세요.","answer":["말차례"],"explanation":["말차례예요.","11쪽이에요.","순서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#24','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C1',4,'essay','teacher','지도서 84~85쪽 평가 — 좋아하는 동물을 「동물 이름 / 사는 곳 / 좋아하는 까닭」을 넣어 친구들 앞에서 발표할 말로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u1-C1","difficulty":4,"kind":"essay","stem":"지도서 84~85쪽 평가 — 좋아하는 동물을 「동물 이름 / 사는 곳 / 좋아하는 까닭」을 넣어 친구들 앞에서 발표할 말로 쓰세요.","answer_guide":{"answer":"예: 제가 좋아하는 동물은 펭귄입니다. 펭귄은 추운 남극에 삽니다. 뒤뚱뒤뚱 걷는 모습이 귀여워서 좋아합니다.","scoring_points":["동물 이름과 사는 곳을 썼어요","좋아하는 까닭을 썼어요"]},"explanation":["발표할 말이에요.","지도서 85쪽이에요.","자신 있게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#25','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C12',4,'essay','teacher','지도서 86~87쪽 평가 — 학급 친구들에게 소개하고 싶은 사람을 정해 특징 두 가지를 넣어 소개하는 글을 3~5문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u1-C12","difficulty":4,"kind":"essay","stem":"지도서 86~87쪽 평가 — 학급 친구들에게 소개하고 싶은 사람을 정해 특징 두 가지를 넣어 소개하는 글을 3~5문장으로 쓰세요.","answer_guide":{"answer":"예: 제가 소개할 사람은 우리 반 박지후입니다. 지후는 키가 작고 눈웃음이 예쁩니다. 지후는 공룡을 좋아해서 공룡 이름을 다 압니다. 지후는 피아노도 잘 칩니다.","scoring_points":["소개할 사람을 정했어요","특징을 두 가지 넘게 썼어요","3~5문장으로 썼어요"]},"explanation":["소개하는 글이에요.","지도서 86쪽이에요.","특징이 드러나게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#1','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C1',1,'mc','auto','국어활동 6쪽 — 호준이가 말할 때 지현이가 할 일은?',ARRAY['K2-1-u1-X01']::text[],false,'{"seq":1,"concept":"K2-1-u1-C1","difficulty":1,"kind":"mc","stem":"국어활동 6쪽 — 호준이가 말할 때 지현이가 할 일은?","options":[{"t":"말하는 사람을 바라보며 들어요","correct":true},{"t":"떠오르는 노래를 흥얼거려요","mis":"K2-1-u1-X01"},{"t":"계속 다른 곳을 바라보아요","mis":"K2-1-u1-X01"}],"explanation":["바라보며 들어요.","국어활동 6쪽이에요.","듣는 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
