INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#3','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C3',1,'mc','auto','10쪽 만화에서 선생님과 친구들이 대화한 것은?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":3,"concept":"K2-1-u1-C3","difficulty":1,"kind":"mc","stem":"10쪽 만화에서 선생님과 친구들이 대화한 것은?","options":[{"t":"자신의 꿈","correct":true},{"t":"점심 메뉴","mis":"K2-1-u1-X06"},{"t":"축구","mis":"K2-1-u1-X06"}],"explanation":["꿈이에요.","11쪽이에요.","과학자예요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"지금부터 자신의 꿈을 말해 봅시다."},{"who":"동현","text":"제 꿈은 과학자입니다. 왜냐하면 저는……."},{"who":"친구","text":"선생님, 제 꿈도 과학자예요."},{"who":"동현","text":"(속마음) 내 말이 아직 안 끝났는데 왜 갑자기 끼어들지?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
