INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#8','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C13',1,'mc','auto','「바나나」의 알맞은 발음은?',ARRAY['K2-1-u1-X15']::text[],false,'{"seq":8,"concept":"K2-1-u1-C13","difficulty":1,"kind":"mc","stem":"「바나나」의 알맞은 발음은?","options":[{"t":"[바나나]","correct":true},{"t":"[빠나나]","mis":"K2-1-u1-X15"},{"t":"[바나나나]","mis":"K2-1-u1-X15"}],"explanation":["[바나나]예요.","40쪽이에요.","예사소리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#9','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C2',2,'mc','auto','민수가 집에 오면 곱슬이는 어떻게 하나요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":9,"concept":"K2-1-u1-C2","difficulty":2,"kind":"mc","stem":"민수가 집에 오면 곱슬이는 어떻게 하나요?","options":[{"t":"겅중겅중 높이 뛰어오르며 반겨 줘요","correct":true},{"t":"숨어요","mis":"K2-1-u1-X06"},{"t":"짖기만 해요","mis":"K2-1-u1-X06"}],"explanation":["반겨 줘요.","9쪽이에요.","하는 일이에요."],"asset":{"type":"passage","lines":["저는 강아지를 기르고 있습니다. 곱슬곱슬한 털이 많아 이름도 곱슬이입니다.","몸집은 작지만 귀는 아주 커서 얼굴을 다 덮을 정도입니다.","눈은 동그라면서 크고, 코는 까만색이며 코끝은 반질거립니다.","제가 학교에 갔다 오면 겅중겅중 높이 뛰어오르며 반겨 줍니다.","곱슬이는 우리 집 재롱둥이입니다."],"title":"『국어』 9쪽 민수가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#10','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C4',2,'mc','auto','호준이가 지현이의 말을 듣다가 궁금한 점이 생기면?',ARRAY['K2-1-u1-X02','K2-1-u1-X01']::text[],false,'{"seq":10,"concept":"K2-1-u1-C4","difficulty":2,"kind":"mc","stem":"호준이가 지현이의 말을 듣다가 궁금한 점이 생기면?","options":[{"t":"말이 끝날 때까지 기다렸다가 물어봐요","correct":true},{"t":"바로 끼어들어 물어봐요","mis":"K2-1-u1-X02"},{"t":"그냥 잊어버려요","mis":"K2-1-u1-X01"}],"explanation":["기다려요.","국어활동 7쪽이에요.","말차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#11','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C5',2,'mc','auto','라라가 신발을 좋아하는 까닭은?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":11,"concept":"K2-1-u1-C5","difficulty":2,"kind":"mc","stem":"라라가 신발을 좋아하는 까닭은?","options":[{"t":"옷은 물려받지만 신발은 늘 새것이라서","correct":true},{"t":"신발이 비싸서","mis":"K2-1-u1-X06"},{"t":"오빠들이 신발을 싫어해서","mis":"K2-1-u1-X06"}],"explanation":["늘 새것이에요.","13쪽이에요.","물려받지 않아요."],"asset":{"type":"passage","lines":["라라는 오빠 셋의 옷을 물려 입지만, 신발만은 늘 새것이에요.","어느 날 라라는 햇빛에 반짝이는 멋진 새 신발을 만났어요.","소풍 날, 라라는 오빠들과 시냇물을 따라 모험을 떠났어요.","그러다 반짝이 신발 한 짝이 시냇물에 떠내려갔어요.","오빠들은 남은 한 짝을 화분, 연필꽂이, 모빌로 쓰자고 했어요.","라라는 짝짝이가 되어도 남은 신발을 계속 신고 다녔어요.","친구가 짝짝이라고 흉을 보아도 라라는 괜찮다고 했어요."],"title":"『국어』 12~27쪽 「세상에 둘도 없는 반짝이 신발」(제인 고드윈) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#12','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C7',2,'mc','auto','친구의 소중한 물건 소개가 끝난 뒤 알맞은 질문은?',ARRAY['K2-1-u1-X02','K2-1-u1-X05']::text[],false,'{"seq":12,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"친구의 소중한 물건 소개가 끝난 뒤 알맞은 질문은?","options":[{"t":"「누가 준 물건이야?」","correct":true},{"t":"(소개 중간에) 「나도 그거 있어!」","mis":"K2-1-u1-X02"},{"t":"「그거 말고 내 거 볼래?」","mis":"K2-1-u1-X05"}],"explanation":["관련 질문이에요.","지도서 68쪽이에요.","끝난 뒤예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
