INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#14','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C10',2,'mc','auto','박준형의 글에 더하면 좋은 것은?',ARRAY['K2-1-u1-X12','K2-1-u1-X09']::text[],false,'{"seq":14,"concept":"K2-1-u1-C10","difficulty":2,"kind":"mc","stem":"박준형의 글에 더하면 좋은 것은?","options":[{"t":"맨 앞에 자신의 이름","correct":true},{"t":"친구가 먹은 음식","mis":"K2-1-u1-X12"},{"t":"더할 것이 없어요","mis":"K2-1-u1-X09"}],"explanation":["이름이에요.","지도서 76쪽이에요.","누구인지 알려요."],"asset":{"type":"passage","lines":["저는 안경을 쓰고 말랐습니다.","저는 블록 조립을 좋아하고 모양 만들기를 잘합니다.","저번에는 블록으로 만화 캐릭터를 만들어서 칭찬을 받았습니다.","저는 커서 로봇 과학자가 되고 싶습니다."],"title":"지도서 박준형이 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#15','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C11',2,'mc','auto','친구 글을 칭찬하는 말로 알맞은 것은?',ARRAY['K2-1-u1-X14','K2-1-u1-X13']::text[],false,'{"seq":15,"concept":"K2-1-u1-C11","difficulty":2,"kind":"mc","stem":"친구 글을 칭찬하는 말로 알맞은 것은?","options":[{"t":"「소개를 자세히 써서 너에 대해 잘 알게 된 것 같아.」","correct":true},{"t":"「글씨가 삐뚤어.」","mis":"K2-1-u1-X14"},{"t":"「내 글이 더 길어.」","mis":"K2-1-u1-X13"}],"explanation":["내용을 칭찬해요.","지도서 77쪽이에요.","칭찬 쪽지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
