INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#18','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C12',3,'error','auto','민희의 글에서 빼야 할 문장은?',ARRAY['K2-1-u1-X12']::text[],false,'{"seq":18,"concept":"K2-1-u1-C12","difficulty":3,"kind":"error","stem":"민희의 글에서 빼야 할 문장은?","options":[{"t":"「제 동생은 생일에 친구들을 초대하려 합니다.」","correct":true,"mis_target":"K2-1-u1-X12"},{"t":"「저는 눈이 큽니다.」","mis":"K2-1-u1-X12"},{"t":"「음식은 된장찌개를 좋아합니다.」","mis":"K2-1-u1-X12"}],"explanation":["동생 이야기예요.","국어활동 11쪽이에요.","관계없어요."],"asset":{"type":"passage","lines":["제 이름은 김민희입니다. 저는 2학년입니다.","저는 눈이 큽니다. 좋아하는 색깔은 주황색입니다.","음식은 된장찌개를 좋아합니다.","제 친구는 지난 주말에 자전거를 탔습니다.","저는 종이접기를 잘합니다.","달리기도 잘한다는 말을 많이 듣습니다.","제 동생은 저와 같이 노는 것을 좋아합니다.","제 동생은 생일에 친구들을 초대하려 합니다."],"title":"『국어활동』 11쪽 민희가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#19','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C8',3,'ox','auto','「저는 김서준입니다. 저는 달리기를 좋아합니다.」만 써도 자신을 충분히 소개한 글이다.',ARRAY['K2-1-u1-X10']::text[],false,'{"seq":19,"concept":"K2-1-u1-C8","difficulty":3,"kind":"ox","stem":"「저는 김서준입니다. 저는 달리기를 좋아합니다.」만 써도 자신을 충분히 소개한 글이다.","answer":"X","reason_options":[{"t":"모습·잘하는 것 등이 없어 서준이를 잘 알 수 없어서","correct":true},{"t":"짧을수록 좋아서","mis":"K2-1-u1-X10"}],"mis":"K2-1-u1-X10","explanation":["더 자세히요.","29쪽이에요.","지도서 72쪽이에요."],"asset":{"type":"passage","lines":["㉮ 저는 김서준입니다. 저는 달리기를 좋아합니다.","㉯ 저는 정하윤입니다. 저는 머리를 묶고 다닙니다.","지금은 노란색 긴팔옷을 입고 있습니다.","저는 종이접기를 좋아해서 항상 색종이를 가지고 다닙니다.","저는 그림을 잘 그립니다.","만화 주인공 그림을 그려서 친구에게 주기도 합니다."],"title":"『국어』 29쪽 서준이와 하윤이가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#20','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C10',3,'mc','auto','39쪽 「자신의 특징을 한 가지만 쓴다.」를 바르게 고치면?',ARRAY['K2-1-u1-X10','K2-1-u1-X13']::text[],false,'{"seq":20,"concept":"K2-1-u1-C10","difficulty":3,"kind":"mc","stem":"39쪽 「자신의 특징을 한 가지만 쓴다.」를 바르게 고치면?","options":[{"t":"좋아하는 것, 잘하는 것 등 특징이 잘 드러나게 쓴다","correct":true},{"t":"특징은 쓰지 않는다","mis":"K2-1-u1-X10"},{"t":"특징을 끝없이 길게 쓴다","mis":"K2-1-u1-X13"}],"explanation":["여러 특징이에요.","지도서 82쪽이에요.","보충 학습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#21','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C5',3,'ox','auto','한 짝만 남은 신발은 쓸모없으니 라라도 버렸어야 했다.',ARRAY['K2-1-u1-X07']::text[],false,'{"seq":21,"concept":"K2-1-u1-C5","difficulty":3,"kind":"ox","stem":"한 짝만 남은 신발은 쓸모없으니 라라도 버렸어야 했다.","answer":"X","reason_options":[{"t":"한 짝이라도 라라에게는 소중한 신발이라서","correct":true},{"t":"짝이 안 맞으면 신발이 아니라서","mis":"K2-1-u1-X07"}],"mis":"K2-1-u1-X07","explanation":["소중해요.","26쪽이에요.","라라의 마음이에요."],"asset":{"type":"passage","lines":["라라는 오빠 셋의 옷을 물려 입지만, 신발만은 늘 새것이에요.","어느 날 라라는 햇빛에 반짝이는 멋진 새 신발을 만났어요.","소풍 날, 라라는 오빠들과 시냇물을 따라 모험을 떠났어요.","그러다 반짝이 신발 한 짝이 시냇물에 떠내려갔어요.","오빠들은 남은 한 짝을 화분, 연필꽂이, 모빌로 쓰자고 했어요.","라라는 짝짝이가 되어도 남은 신발을 계속 신고 다녔어요.","친구가 짝짝이라고 흉을 보아도 라라는 괜찮다고 했어요."],"title":"『국어』 12~27쪽 「세상에 둘도 없는 반짝이 신발」(제인 고드윈) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#22','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C6',3,'mc','auto','「모험」을 알맞게 쓴 문장은?',ARRAY['K2-1-u1-X08']::text[],false,'{"seq":22,"concept":"K2-1-u1-C6","difficulty":3,"kind":"mc","stem":"「모험」을 알맞게 쓴 문장은?","options":[{"t":"「우리는 숲속 동굴로 모험을 떠났다.」","correct":true},{"t":"「신발 한 모험을 잃었다.」","mis":"K2-1-u1-X08"},{"t":"「친구가 내 모험을 보았다.」","mis":"K2-1-u1-X08"}],"explanation":["모험이에요.","27쪽이에요.","문장에 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#23','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C6',4,'sa','auto','둘이 어울려 한 쌍을 이루는 것의 각각을 세는 단위를 한 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u1-C6","difficulty":4,"kind":"sa","stem":"둘이 어울려 한 쌍을 이루는 것의 각각을 세는 단위를 한 글자로 쓰세요.","answer":["짝"],"explanation":["짝이에요.","27쪽이에요.","신발 한 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#24','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C4',4,'essay','teacher','동현이에게 끼어든 친구가 말차례를 지켰다면 어떻게 말했을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u1-C4","difficulty":4,"kind":"essay","stem":"동현이에게 끼어든 친구가 말차례를 지켰다면 어떻게 말했을지 쓰세요.","answer_guide":{"answer":"예: 동현이의 말이 끝날 때까지 기다렸다가 「선생님, 저도 말해도 될까요? 제 꿈도 과학자예요.」라고 말했을 것이다.","scoring_points":["기다렸어요","말해도 되는지 물었어요"]},"explanation":["묻고 말해요.","11쪽이에요.","지도서 61쪽이에요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"지금부터 자신의 꿈을 말해 봅시다."},{"who":"동현","text":"제 꿈은 과학자입니다. 왜냐하면 저는……."},{"who":"친구","text":"선생님, 제 꿈도 과학자예요."},{"who":"동현","text":"(속마음) 내 말이 아직 안 끝났는데 왜 갑자기 끼어들지?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#25','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C10',4,'essay','teacher','나를 소개하는 글을 3~5문장으로 쓰세요(이름·모습·좋아하는 것·잘하는 것 넣기).','{}'::text[],false,'{"seq":25,"concept":"K2-1-u1-C10","difficulty":4,"kind":"essay","stem":"나를 소개하는 글을 3~5문장으로 쓰세요(이름·모습·좋아하는 것·잘하는 것 넣기).","answer_guide":{"answer":"예: 저는 오하람입니다. 저는 앞머리가 있고 웃을 때 눈이 반달이 됩니다. 저는 고양이를 좋아해서 고양이 그림을 자주 그립니다. 저는 훌라후프를 잘 돌립니다.","scoring_points":["이름을 썼어요","모습·좋아하는 것·잘하는 것을 썼어요","3~5문장으로 썼어요"]},"explanation":["나를 소개해요.","34쪽이에요.","지도서 76쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#1','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C1',1,'mc','auto','평가 자료 1 — 친구의 동물 소개를 들을 때 알맞은 것은?',ARRAY['K2-1-u1-X01']::text[],false,'{"seq":1,"concept":"K2-1-u1-C1","difficulty":1,"kind":"mc","stem":"평가 자료 1 — 친구의 동물 소개를 들을 때 알맞은 것은?","options":[{"t":"고개를 끄덕이거나 미소를 지으며 들어요","correct":true},{"t":"지루하면 엎드려요","mis":"K2-1-u1-X01"},{"t":"내 차례만 기다리며 딴생각해요","mis":"K2-1-u1-X01"}],"explanation":["반응하며 들어요.","지도서 84쪽이에요.","듣는 자세예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#2','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C1',1,'mc','auto','평가 자료 1 — 여러 사람 앞에서 발표할 때 스스로 확인할 내용은?',ARRAY['K2-1-u1-X04']::text[],false,'{"seq":2,"concept":"K2-1-u1-C1","difficulty":1,"kind":"mc","stem":"평가 자료 1 — 여러 사람 앞에서 발표할 때 스스로 확인할 내용은?","options":[{"t":"또박또박, 큰 소리로, 듣는 사람을 바라보며 말했나요?","correct":true},{"t":"가장 빨리 말했나요?","mis":"K2-1-u1-X04"},{"t":"종이만 보고 읽었나요?","mis":"K2-1-u1-X04"}],"explanation":["바른 자세예요.","지도서 85쪽이에요.","확인할 내용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#3','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C3',1,'mc','auto','말차례는 누구에게 먼저 있나요?',ARRAY['K2-1-u1-X03']::text[],false,'{"seq":3,"concept":"K2-1-u1-C3","difficulty":1,"kind":"mc","stem":"말차례는 누구에게 먼저 있나요?","options":[{"t":"먼저 말을 시작한 사람","correct":true},{"t":"목소리가 큰 사람","mis":"K2-1-u1-X03"},{"t":"나중에 온 사람","mis":"K2-1-u1-X03"}],"explanation":["먼저 말한 사람이에요.","지도서 61쪽이에요.","기다려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#4','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C4',1,'mc','auto','국어활동 7쪽 — 호준이의 말을 듣다가 하고 싶은 말이 생긴 지현이는?',ARRAY['K2-1-u1-X03','K2-1-u1-X02']::text[],false,'{"seq":4,"concept":"K2-1-u1-C4","difficulty":1,"kind":"mc","stem":"국어활동 7쪽 — 호준이의 말을 듣다가 하고 싶은 말이 생긴 지현이는?","options":[{"t":"손짓을 하며 말할 기회를 얻어요","correct":true},{"t":"큰 소리로 외쳐요","mis":"K2-1-u1-X03"},{"t":"바로 끼어들어요","mis":"K2-1-u1-X02"}],"explanation":["손짓으로요.","국어활동 7쪽이에요.","기회를 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#5','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C5',1,'mc','auto','라라에게 오빠는 몇 명 있나요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":5,"concept":"K2-1-u1-C5","difficulty":1,"kind":"mc","stem":"라라에게 오빠는 몇 명 있나요?","options":[{"t":"셋","correct":true},{"t":"하나","mis":"K2-1-u1-X06"},{"t":"다섯","mis":"K2-1-u1-X06"}],"explanation":["셋이에요.","12쪽이에요.","월터·맥스·핀이에요."],"asset":{"type":"passage","lines":["라라는 오빠 셋의 옷을 물려 입지만, 신발만은 늘 새것이에요.","어느 날 라라는 햇빛에 반짝이는 멋진 새 신발을 만났어요.","소풍 날, 라라는 오빠들과 시냇물을 따라 모험을 떠났어요.","그러다 반짝이 신발 한 짝이 시냇물에 떠내려갔어요.","오빠들은 남은 한 짝을 화분, 연필꽂이, 모빌로 쓰자고 했어요.","라라는 짝짝이가 되어도 남은 신발을 계속 신고 다녔어요.","친구가 짝짝이라고 흉을 보아도 라라는 괜찮다고 했어요."],"title":"『국어』 12~27쪽 「세상에 둘도 없는 반짝이 신발」(제인 고드윈) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
