INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#7','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C8',1,'mc','auto','소개하는 내용이 잘 드러나게 쓴 글은?',ARRAY['K2-1-u1-X10']::text[],false,'{"seq":7,"concept":"K2-1-u1-C8","difficulty":1,"kind":"mc","stem":"소개하는 내용이 잘 드러나게 쓴 글은?","options":[{"t":"글 ㉯","correct":true},{"t":"글 ㉮","mis":"K2-1-u1-X10"},{"t":"둘 다 같아요","mis":"K2-1-u1-X10"}],"explanation":["글 ㉯예요.","29쪽이에요.","자세해요."],"asset":{"type":"passage","lines":["㉮ 저는 김서준입니다. 저는 달리기를 좋아합니다.","㉯ 저는 정하윤입니다. 저는 머리를 묶고 다닙니다.","지금은 노란색 긴팔옷을 입고 있습니다.","저는 종이접기를 좋아해서 항상 색종이를 가지고 다닙니다.","저는 그림을 잘 그립니다.","만화 주인공 그림을 그려서 친구에게 주기도 합니다."],"title":"『국어』 29쪽 서준이와 하윤이가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
