INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#9','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C2',2,'match','auto','곱슬이의 생김새를 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u1-C2","difficulty":2,"kind":"match","stem":"곱슬이의 생김새를 이어 보세요.","pairs":[{"l":"귀","r":"얼굴을 다 덮을 정도로 커요"},{"l":"눈","r":"동그라면서 커요"},{"l":"코","r":"까만색이고 반질거려요"}],"mis":"K2-1-u1-X06","explanation":["생김새예요.","9쪽이에요.","자세해요."],"asset":{"type":"passage","lines":["저는 강아지를 기르고 있습니다. 곱슬곱슬한 털이 많아 이름도 곱슬이입니다.","몸집은 작지만 귀는 아주 커서 얼굴을 다 덮을 정도입니다.","눈은 동그라면서 크고, 코는 까만색이며 코끝은 반질거립니다.","제가 학교에 갔다 오면 겅중겅중 높이 뛰어오르며 반겨 줍니다.","곱슬이는 우리 집 재롱둥이입니다."],"title":"『국어』 9쪽 민수가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
