INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#17','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C9',3,'error','auto','지도서 「친구 소개」를 읽고 고쳐야 할 점은?',ARRAY['K2-1-u1-X09','K2-1-u1-X12','K2-1-u1-X10']::text[],false,'{"seq":17,"concept":"K2-1-u1-C9","difficulty":3,"kind":"error","stem":"지도서 「친구 소개」를 읽고 고쳐야 할 점은?","options":[{"t":"누구를 소개하는지 이름이 없고, 소개하는 내용이 자세하지 않아요","correct":true,"mis_target":"K2-1-u1-X09"},{"t":"「엄마」를 「아빠」로 고쳐요","mis":"K2-1-u1-X12"},{"t":"고칠 곳이 없어요","mis":"K2-1-u1-X10"}],"explanation":["이름부터요.","지도서 73쪽이에요.","소개하는 방법이에요."],"asset":{"type":"passage","lines":["엄마, 걔는 우리 반이에요. 축구를 좋아하는 것 같아요.","집에 올 때 만났는데 어디 사는지 모르겠어요."],"title":"지도서 「친구 소개」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#18','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C12',3,'error','auto','친구가 이모를 소개하는 글을 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#19','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C13',3,'ox','auto','세게 말하려고 「자르다」를 [짜르다]로 소리 내는 것은 바른 발음이다.',ARRAY['K2-1-u1-X15']::text[],false,'{"seq":19,"concept":"K2-1-u1-C13","difficulty":3,"kind":"ox","stem":"세게 말하려고 「자르다」를 [짜르다]로 소리 내는 것은 바른 발음이다.","answer":"X","reason_options":[{"t":"된소리로 세게 내는 것은 바른 발음이 아니어서","correct":true},{"t":"세게 말할수록 바른 발음이라서","mis":"K2-1-u1-X15"}],"mis":"K2-1-u1-X15","explanation":["[자르다]예요.","지도서 83쪽이에요.","바른 발음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#20','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C10',3,'mc','auto','박준형의 글에서 잘 쓴 점은?',ARRAY['K2-1-u1-X09','K2-1-u1-X12']::text[],false,'{"seq":20,"concept":"K2-1-u1-C10","difficulty":3,"kind":"mc","stem":"박준형의 글에서 잘 쓴 점은?","options":[{"t":"좋아하는 것·잘하는 것·칭찬받은 일·장래 희망을 자세히 썼어요","correct":true},{"t":"이름을 맨 앞에 썼어요","mis":"K2-1-u1-X09"},{"t":"친구 이야기를 많이 썼어요","mis":"K2-1-u1-X12"}],"explanation":["자세해요.","지도서 76쪽이에요.","이름은 빠졌어요."],"asset":{"type":"passage","lines":["저는 안경을 쓰고 말랐습니다.","저는 블록 조립을 좋아하고 모양 만들기를 잘합니다.","저번에는 블록으로 만화 캐릭터를 만들어서 칭찬을 받았습니다.","저는 커서 로봇 과학자가 되고 싶습니다."],"title":"지도서 박준형이 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#21','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C5',3,'mc','auto','라라에게 앞으로 일어날 일로 흐름에 맞는 것은?',ARRAY['K2-1-u1-X07','K2-1-u1-X06']::text[],false,'{"seq":21,"concept":"K2-1-u1-C5","difficulty":3,"kind":"mc","stem":"라라에게 앞으로 일어날 일로 흐름에 맞는 것은?","options":[{"t":"짝짝이 신발을 신고 다니다가 잃어버린 한 짝을 찾게 되는 일","correct":true},{"t":"신발을 모두 버리는 일","mis":"K2-1-u1-X07"},{"t":"갑자기 오빠가 되는 일","mis":"K2-1-u1-X06"}],"explanation":["흐름에 맞아요.","지도서 66쪽이에요.","소중히 여겨요."],"asset":{"type":"passage","lines":["라라는 오빠 셋의 옷을 물려 입지만, 신발만은 늘 새것이에요.","어느 날 라라는 햇빛에 반짝이는 멋진 새 신발을 만났어요.","소풍 날, 라라는 오빠들과 시냇물을 따라 모험을 떠났어요.","그러다 반짝이 신발 한 짝이 시냇물에 떠내려갔어요.","오빠들은 남은 한 짝을 화분, 연필꽂이, 모빌로 쓰자고 했어요.","라라는 짝짝이가 되어도 남은 신발을 계속 신고 다녔어요.","친구가 짝짝이라고 흉을 보아도 라라는 괜찮다고 했어요."],"title":"『국어』 12~27쪽 「세상에 둘도 없는 반짝이 신발」(제인 고드윈) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#22','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C12',3,'mc','auto','부모님께 친구를 소개하는 글을 쓰기 전에 먼저 정할 것은?',ARRAY['K2-1-u1-X12','K2-1-u1-X14']::text[],false,'{"seq":22,"concept":"K2-1-u1-C12","difficulty":3,"kind":"mc","stem":"부모님께 친구를 소개하는 글을 쓰기 전에 먼저 정할 것은?","options":[{"t":"누구를 소개할지와 소개하고 싶은 까닭","correct":true},{"t":"봉투 색깔","mis":"K2-1-u1-X12"},{"t":"글자 크기","mis":"K2-1-u1-X14"}],"explanation":["대상과 까닭이에요.","지도서 80쪽이에요.","정하고 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#23','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C2',4,'sa','auto','민수는 곱슬이를 우리 집 ○○○이라고 했어요. 빈칸 세 글자를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u1-C2","difficulty":4,"kind":"sa","stem":"민수는 곱슬이를 우리 집 ○○○이라고 했어요. 빈칸 세 글자를 쓰세요.","answer":["재롱둥이"],"explanation":["재롱둥이예요.","9쪽이에요.","끝 문장이에요."],"asset":{"type":"passage","lines":["저는 강아지를 기르고 있습니다. 곱슬곱슬한 털이 많아 이름도 곱슬이입니다.","몸집은 작지만 귀는 아주 커서 얼굴을 다 덮을 정도입니다.","눈은 동그라면서 크고, 코는 까만색이며 코끝은 반질거립니다.","제가 학교에 갔다 오면 겅중겅중 높이 뛰어오르며 반겨 줍니다.","곱슬이는 우리 집 재롱둥이입니다."],"title":"『국어』 9쪽 민수가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#24','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C7',4,'essay','teacher','나에게 소중한 물건을 「이름 / 색깔과 모양 / 소중한 까닭」을 넣어 소개하는 말을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u1-C7","difficulty":4,"kind":"essay","stem":"나에게 소중한 물건을 「이름 / 색깔과 모양 / 소중한 까닭」을 넣어 소개하는 말을 쓰세요.","answer_guide":{"answer":"예: 제 소중한 물건은 파란 필통입니다. 하늘색 바탕에 고래 그림이 있습니다. 할머니께서 입학 선물로 사 주셔서 소중합니다.","scoring_points":["물건 이름을 썼어요","색깔이나 모양을 썼어요","소중한 까닭을 썼어요"]},"explanation":["소개해요.","27쪽이에요.","궁금해할 내용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#25','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C9',4,'essay','teacher','지도서 「친구 소개」를 소개하는 글 쓰는 방법에 맞게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u1-C9","difficulty":4,"kind":"essay","stem":"지도서 「친구 소개」를 소개하는 글 쓰는 방법에 맞게 고쳐 쓰세요.","answer_guide":{"answer":"예: 엄마, 우리 반 친구 이도윤을 소개할게요. 도윤이는 키가 크고 웃음이 많아요. 축구를 좋아해서 쉬는 시간마다 공을 차고, 골을 잘 넣어요.","scoring_points":["이름을 넣었어요","모습·좋아하는 것·잘하는 것을 넣었어요"]},"explanation":["고쳐 써요.","지도서 73쪽이에요.","보충해요."],"asset":{"type":"passage","lines":["엄마, 걔는 우리 반이에요. 축구를 좋아하는 것 같아요.","집에 올 때 만났는데 어디 사는지 모르겠어요."],"title":"지도서 「친구 소개」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#1','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C1',1,'mc','auto','중요한 내용을 잊지 않으려면 발표를 어떻게 들으면 좋을까요?',ARRAY['K2-1-u1-X01']::text[],false,'{"seq":1,"concept":"K2-1-u1-C1","difficulty":1,"kind":"mc","stem":"중요한 내용을 잊지 않으려면 발표를 어떻게 들으면 좋을까요?","options":[{"t":"중요한 내용은 쓰면서 들어요","correct":true},{"t":"다 외우려고 눈을 감아요","mis":"K2-1-u1-X01"},{"t":"나중에 친구에게 다시 물어요","mis":"K2-1-u1-X01"}],"explanation":["쓰면서 들어요.","8쪽 1번이에요.","메모해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#2','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C1',1,'mc','auto','자신의 말차례가 되었을 때는?',ARRAY['K2-1-u1-X04']::text[],false,'{"seq":2,"concept":"K2-1-u1-C1","difficulty":1,"kind":"mc","stem":"자신의 말차례가 되었을 때는?","options":[{"t":"하고 싶은 말을 끝까지 분명하게 해요","correct":true},{"t":"조금 말하고 그만둬요","mis":"K2-1-u1-X04"},{"t":"작게 중얼거려요","mis":"K2-1-u1-X04"}],"explanation":["끝까지 분명하게요.","38쪽이에요.","내 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#3','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C3',1,'mc','auto','동현이가 당황한 까닭은?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":3,"concept":"K2-1-u1-C3","difficulty":1,"kind":"mc","stem":"동현이가 당황한 까닭은?","options":[{"t":"말이 끝나지 않았는데 친구가 끼어들어서","correct":true},{"t":"꿈이 없어서","mis":"K2-1-u1-X06"},{"t":"선생님이 화를 내셔서","mis":"K2-1-u1-X06"}],"explanation":["끼어들었어요.","11쪽이에요.","말이 끊겼어요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"지금부터 자신의 꿈을 말해 봅시다."},{"who":"동현","text":"제 꿈은 과학자입니다. 왜냐하면 저는……."},{"who":"친구","text":"선생님, 제 꿈도 과학자예요."},{"who":"동현","text":"(속마음) 내 말이 아직 안 끝났는데 왜 갑자기 끼어들지?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
