INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#5','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C5',1,'mc','auto','라라가 오빠들에게 물려받지 않는 것은?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":5,"concept":"K2-1-u1-C5","difficulty":1,"kind":"mc","stem":"라라가 오빠들에게 물려받지 않는 것은?","options":[{"t":"속옷과 신발","correct":true},{"t":"모자와 장갑","mis":"K2-1-u1-X06"},{"t":"가방","mis":"K2-1-u1-X06"}],"explanation":["속옷과 신발이에요.","13쪽이에요.","늘 새것이에요."],"asset":{"type":"passage","lines":["라라는 오빠 셋의 옷을 물려 입지만, 신발만은 늘 새것이에요.","어느 날 라라는 햇빛에 반짝이는 멋진 새 신발을 만났어요.","소풍 날, 라라는 오빠들과 시냇물을 따라 모험을 떠났어요.","그러다 반짝이 신발 한 짝이 시냇물에 떠내려갔어요.","오빠들은 남은 한 짝을 화분, 연필꽂이, 모빌로 쓰자고 했어요.","라라는 짝짝이가 되어도 남은 신발을 계속 신고 다녔어요.","친구가 짝짝이라고 흉을 보아도 라라는 괜찮다고 했어요."],"title":"『국어』 12~27쪽 「세상에 둘도 없는 반짝이 신발」(제인 고드윈) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
