INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#9','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C2',2,'mc','auto','민수의 글은 무엇을 하는 글인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":9,"concept":"K2-1-u1-C2","difficulty":2,"kind":"mc","stem":"민수의 글은 무엇을 하는 글인가요?","options":[{"t":"강아지 곱슬이를 소개하는 글","correct":true},{"t":"강아지에게 쓴 편지","mis":"K2-1-u1-X06"},{"t":"강아지와 다툰 일기","mis":"K2-1-u1-X06"}],"explanation":["소개하는 글이에요.","9쪽이에요.","대상과 특징이에요."],"asset":{"type":"passage","lines":["저는 강아지를 기르고 있습니다. 곱슬곱슬한 털이 많아 이름도 곱슬이입니다.","몸집은 작지만 귀는 아주 커서 얼굴을 다 덮을 정도입니다.","눈은 동그라면서 크고, 코는 까만색이며 코끝은 반질거립니다.","제가 학교에 갔다 오면 겅중겅중 높이 뛰어오르며 반겨 줍니다.","곱슬이는 우리 집 재롱둥이입니다."],"title":"『국어』 9쪽 민수가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
