INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#21','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C7',3,'mc','auto','대화를 이어 가는 말과 쓰임을 바르게 짝 지은 것은?',ARRAY['K2-1-u1-X03']::text[],false,'{"seq":21,"concept":"K2-1-u1-C7","difficulty":3,"kind":"mc","stem":"대화를 이어 가는 말과 쓰임을 바르게 짝 지은 것은?","options":[{"t":"「하고 싶은 말 끝난 거니?」 — 말차례를 가져와도 되는지 확인할 때","correct":true},{"t":"「그랬구나.」 — 말차례를 빼앗을 때","mis":"K2-1-u1-X03"},{"t":"「네가 말할 차례야.」 — 내가 계속 말할 때","mis":"K2-1-u1-X03"}],"explanation":["확인해요.","지도서 68쪽이에요.","쓰임이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#22','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C12',3,'mc','auto','좋아하는 사람을 소개할 때 쓰면 안 되는 것은?',ARRAY['K2-1-u1-X12']::text[],false,'{"seq":22,"concept":"K2-1-u1-C12","difficulty":3,"kind":"mc","stem":"좋아하는 사람을 소개할 때 쓰면 안 되는 것은?","options":[{"t":"그 사람 집의 비밀번호","correct":true},{"t":"그 사람이 잘하는 것","mis":"K2-1-u1-X12"},{"t":"그 사람의 모습","mis":"K2-1-u1-X12"}],"explanation":["개인 정보예요.","36쪽이에요.","빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#23','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C10',4,'sa','auto','소개하는 글을 다 쓴 뒤 스스로 확인할 때 쓰는 표를 세 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u1-C10","difficulty":4,"kind":"sa","stem":"소개하는 글을 다 쓴 뒤 스스로 확인할 때 쓰는 표를 세 글자로 쓰세요.","answer":["점검표"],"explanation":["점검표예요.","35쪽이에요.","스스로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#24','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C3',4,'essay','teacher','말차례를 지켜야 하는 까닭을 동현이의 마음과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u1-C3","difficulty":4,"kind":"essay","stem":"말차례를 지켜야 하는 까닭을 동현이의 마음과 함께 쓰세요.","answer_guide":{"answer":"예: 끼어들면 동현이처럼 말하던 사람이 당황하고 하고 싶은 말을 다 하지 못하기 때문이다.","scoring_points":["동현이의 마음을 썼어요","까닭을 썼어요"]},"explanation":["까닭이에요.","11쪽이에요.","지도서 61쪽이에요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"지금부터 자신의 꿈을 말해 봅시다."},{"who":"동현","text":"제 꿈은 과학자입니다. 왜냐하면 저는……."},{"who":"친구","text":"선생님, 제 꿈도 과학자예요."},{"who":"동현","text":"(속마음) 내 말이 아직 안 끝났는데 왜 갑자기 끼어들지?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#25','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C12',4,'essay','teacher','가족 가운데 한 사람을 골라 「나와의 관계(이름) / 모습 / 좋아하는 것 / 잘하는 것」을 넣어 소개하는 글을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u1-C12","difficulty":4,"kind":"essay","stem":"가족 가운데 한 사람을 골라 「나와의 관계(이름) / 모습 / 좋아하는 것 / 잘하는 것」을 넣어 소개하는 글을 쓰세요.","answer_guide":{"answer":"예: 우리 아빠 김도현을 소개합니다. 아빠는 키가 크고 수염이 있습니다. 아빠는 주말마다 등산을 좋아합니다. 아빠는 김치볶음밥을 잘 만듭니다.","scoring_points":["관계와 이름을 썼어요","특징을 두 가지 넘게 썼어요"]},"explanation":["가족 소개예요.","지도서 81쪽이에요.","특징이 드러나게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
